package com.nexus.access.backend.auth;
import java.time.OffsetDateTime; import java.util.UUID; import jakarta.persistence.*; import com.nexus.access.backend.user.User;
@Entity @Table(name="refresh_tokens") public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="token_hash",nullable=false,unique=true,length=64) private String tokenHash; @Column(name="expires_at",nullable=false) private OffsetDateTime expiresAt; @Column(name="revoked_at") private OffsetDateTime revokedAt; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @PrePersist void created(){createdAt=OffsetDateTime.now();} public UUID getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getTokenHash(){return tokenHash;} public void setTokenHash(String v){tokenHash=v;} public OffsetDateTime getExpiresAt(){return expiresAt;} public void setExpiresAt(OffsetDateTime v){expiresAt=v;} public OffsetDateTime getRevokedAt(){return revokedAt;} public void setRevokedAt(OffsetDateTime v){revokedAt=v;} }
